using System.Text;
using System.Text.Json;
using ModelContextProtocol.Client;
using ModelContextProtocol.Protocol;
using Studio5000.Client;
using Studio5000.Core;
using Studio5000.Extensibility;

internal static class StructuralEditsIntegration
{
    internal static async Task RunAsync(string root, ServiceClient client)
    {
        var checks = new List<string>(); void Check(bool success, string message) { if (!success) throw new Exception("FAIL: " + message); checks.Add(message); Console.WriteLine("PASS: " + message); }
        await using var mcp = await McpClient.CreateAsync(new StdioClientTransport(new StdioClientTransportOptions { Command = "powershell.exe", Arguments = ["-NoProfile", "-ExecutionPolicy", "Bypass", "-File", Path.Combine(root, "scripts", "Start-Mcp.ps1")], EnvironmentVariables = new Dictionary<string, string?> { ["STUDIO5000_PLUGIN_ROOT"] = root }, Name = "Focused structural integration" }));
        var catalogResult = await mcp.CallToolAsync("studio_extensions_catalog", new Dictionary<string, object?>()); var catalog = JsonSerializer.Deserialize<ExtensionCatalog>(catalogResult.Content.OfType<TextContentBlock>().First().Text, ProjectService.Json)!;
        var owner = catalog.Extensions.Single(e => e.Id == "logix"); Check(catalog.LoadErrors.Length == 0 && catalog.Extensions.Where(e => e.Id != "fixture").Sum(e => e.Operations.Length) == 157, "Catalog exposes the complete structural workflow without extension errors");
        async Task<CallToolResult> Call(string name, object? request = null, string effect = "read", params (string Key, string Value)[] ids)
        { var arguments = new Dictionary<string, object?>(); if (request is not null) arguments["request"] = request; foreach (var id in ids) arguments[id.Key] = id.Value; return await mcp.CallToolAsync("studio_extensions_" + effect, new Dictionary<string, object?> { ["call"] = new ExtensionCall(owner.Id, name, owner.Generation, JsonSerializer.SerializeToElement(arguments, ProjectService.Json)) }); }
        async Task<T> Tool<T>(string name, object? request = null, string effect = "read", params (string Key, string Value)[] ids)
        { var response = await Call(name, request, effect, ids); if (response.IsError == true) throw new Exception(response.Content.OfType<TextContentBlock>().First().Text); return JsonSerializer.Deserialize<T>(response.Content.OfType<TextContentBlock>().First().Text, ProjectService.Json)!; }
        const string old = "<Tag Name='OldGate' TagType='Base' DataType='BOOL'><Data Format='L5K'>0</Data></Tag>";
        var text = "<?xml version='1.0' encoding='utf-8'?>\r\n<RSLogix5000Content><Controller Name='Demo'><AddOnInstructionDefinitions><EncodedData Name='Native' SignatureID='retain'><![CDATA[opaque\r\n]]></EncodedData></AddOnInstructionDefinitions><Tags>" + old + "<Tag Name='Keep' TagType='Base' DataType='DINT'><Description><![CDATA[line one\r\nline two]]></Description><Data Format='L5K'><![CDATA[41\r\n]]></Data></Tag></Tags><Programs><Program Name='App' MainRoutineName='Main'><Routines><Routine Name='Main' Type='RLL'><RLLContent><Rung Number='0'><Text><![CDATA[XIC(OldGate)OTE(Keep);]]></Text></Rung></RLLContent></Routine></Routines></Program></Programs></Controller></RSLogix5000Content>\r\n";
        var path = Path.Combine(root, "examples", "StructuralGenerated.L5X"); File.WriteAllText(path, text, new UTF8Encoding(true)); var project = await client.PostAsync<ProjectInfo>("/api/projects", new RegisterRequest(path));
        const string tagPath = "/RSLogix5000Content/Controller/Tags/Tag[@Name='OldGate']"; const string logic = "/RSLogix5000Content/Controller/Programs/Program/Routines/Routine/RLLContent/Rung/Text";
        var tag = await Tool<StructuralContext>("studio_structural_edit_context", new StructuralContextRequest(project.Id, project.CurrentSha256, 0, tagPath)); var code = await Tool<StructuralContext>("studio_structural_edit_context", new StructuralContextRequest(project.Id, project.CurrentSha256, 0, logic));
        Check(tag.Targets.Single().ElementSha256.Length == 64 && tag.Targets.Single().ValueSetSha256?.Length == 64, "Context returns exact raw component and stored-value fingerprints");
        var planPath = Path.Combine(root, "examples", "StructuralReviewedPlan.json"); File.WriteAllText(planPath, "{\"kind\":\"generated reviewed plan\"}");
        var request = new StructuralEditRequest(project.Id, project.CurrentSha256, 0, new(planPath, ProjectService.Hash(File.ReadAllBytes(planPath))), new([new("App", "Main")], [new("OldGate")], [], AcknowledgeIncompleteBindings: true, ValueDispositions: [new(new("OldGate"), "remove", "Generated fixture: captured gate state explicitly retired.")]), [new("remove_element", tagPath, tag.Targets[0].ElementSha256), new("set_text", logic, code.Targets[0].ElementSha256, "NOP();")]);
        Check((await Call("studio_structural_edit_preview", request)).IsError == true, "Read channel cannot create a retained structural preview");
        var preview = await Tool<StructuralEditPreview>("studio_structural_edit_preview", request, "preview");
        Check(preview.CanApply && preview.XmlPreservation == "structural-byte-spans-v1" && preview.PreviewReceipt is not null && preview.ValueDispositions.Single().Action == "remove", "Preview retains source, plan, scope, byte-preservation and saved-state evidence");
        Check(ProjectService.Hash(await client.DownloadAsync(preview.PreviewReceipt!.Id)) == preview.PreviewReceipt.Sha256 && (await client.GetAsync<ProjectInfo>("/api/projects/" + project.Id)).Revision == 0, "Preview receipt is immutable and the source revision is unchanged");
        var status = await Tool<StructuralEditStatus>("studio_structural_edit_status", ids: [("previewReceiptId", preview.PreviewReceipt.Id), ("expectedSha256", preview.PreviewReceipt.Sha256)]); Check(status.Status == "previewed", "Retained status reconciles a preview without mutation");
        var apply = new StructuralApplyRequest(request, preview.ReviewSha256, preview.PreviewReceipt.Id, preview.PreviewReceipt.Sha256);
        Check((await Call("studio_structural_edit_apply", apply)).IsError == true && (await Call("studio_structural_edit_apply", apply with { ExpectedReviewSha256 = new string('0', 64) }, "apply")).IsError == true, "Channel and review guards reject unauthorized or stale structural apply");
        var result = await Tool<StructuralEditResult>("studio_structural_edit_apply", apply, "apply"); var expected = new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(text.Replace(old, "").Replace("XIC(OldGate)OTE(Keep);", "NOP();"))).ToArray();
        Check((await client.DownloadAsync(result.Candidate.Id)).SequenceEqual(expected) && result.ReviewOnly && result.NativeAcceptance == "not-performed", "Candidate preserves every unselected byte including annotation CRLF and opaque libraries");
        Check(result.Project.Id != project.Id && ProjectService.Hash(File.ReadAllBytes(path)) == project.SourceSha256 && (await client.GetAsync<ProjectInfo>("/api/projects/" + project.Id)).Revision == 0, "Apply creates a separate project without changing source files or managed input");
        Check(ProjectService.Hash(await client.DownloadAsync(result.Receipt.Id)) == result.Receipt.Sha256, "Apply receipt retains a hash-verified complete review and immutable candidate");
        var repeated = await Tool<StructuralEditResult>("studio_structural_edit_apply", apply, "apply"); Check(repeated.Project.Id == result.Project.Id && repeated.Candidate.Id == result.Candidate.Id, "Exact completed apply reconciles without duplicating the candidate");
        status = await Tool<StructuralEditStatus>("studio_structural_edit_status", ids: [("previewReceiptId", preview.PreviewReceipt.Id), ("expectedSha256", preview.PreviewReceipt.Sha256)]); Check(status.Status == "applied" && status.Result?.Receipt.Id == result.Receipt.Id, "Status retains the completed receipt and result without reapplying edits");
        const string aoi = "<AddOnInstructionDefinition Name='ApplicationAdapter' Class='Standard'><Parameters><Parameter Name='Value' DataType='DINT'/></Parameters><Routines><Routine Name='Logic' Type='RLL'><RLLContent><Rung Number='0'><Text><![CDATA[NOP();\r\n]]></Text></Rung></RLLContent></Routine></Routines></AddOnInstructionDefinition>";
        var referencePath = Path.Combine(root, "examples", "StructuralReference.L5X"); File.WriteAllText(referencePath, "<RSLogix5000Content><Controller Name='Reference'><AddOnInstructionDefinitions>" + aoi + "</AddOnInstructionDefinitions></Controller></RSLogix5000Content>"); var referenceProject = await client.PostAsync<ProjectInfo>("/api/projects", new RegisterRequest(referencePath));
        var referenceContext = await Tool<StructuralContext>("studio_structural_edit_context", new StructuralContextRequest(referenceProject.Id, referenceProject.CurrentSha256, 0, "/RSLogix5000Content/Controller/AddOnInstructionDefinitions/AddOnInstructionDefinition"));
        var destination = await Tool<StructuralContext>("studio_structural_edit_context", new StructuralContextRequest(project.Id, project.CurrentSha256, 0, "/RSLogix5000Content/Controller/AddOnInstructionDefinitions"));
        var referenceRequest = new StructuralEditRequest(project.Id, project.CurrentSha256, 0, request.Plan, new([], [], [], AcknowledgeIncompleteBindings: true, ReferenceAdditions: [new("adapter", "aoi", "ApplicationAdapter", new(referencePath, referenceProject.CurrentSha256), referenceContext.Targets[0].XPath, referenceContext.Targets[0].ElementSha256)]), [new("add_reference", destination.Targets[0].XPath, destination.Targets[0].ElementSha256, ReferenceKey: "adapter")]);
        var referencePreview = await Tool<StructuralEditPreview>("studio_structural_edit_preview", referenceRequest, "preview"); Check(referencePreview.CanApply && referencePreview.ReferenceBindings.Single().SourceSha256 == referenceProject.CurrentSha256, "MCP reference addition binds exact source-file and raw node hashes without inline library mutation");
        var referenceResult = await Tool<StructuralEditResult>("studio_structural_edit_apply", new StructuralApplyRequest(referenceRequest, referencePreview.ReviewSha256, referencePreview.PreviewReceipt!.Id, referencePreview.PreviewReceipt.Sha256), "apply");
        var referenceExpected = new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(text.Replace("</AddOnInstructionDefinitions>", aoi + "</AddOnInstructionDefinitions>"))).ToArray(); Check((await client.DownloadAsync(referenceResult.Candidate.Id)).SequenceEqual(referenceExpected), "Reference-only AOI addition preserves the exact copied text and all existing source/library bytes");
        var nativeRequest = new LogixValidationRequest("native-readback", new(result.Project.Id, result.Project.CurrentSha256), Reference: new(result.Project.Id, result.Project.CurrentSha256)); var readback = await Tool<LogixValidationReport>("studio_validation_preview", nativeRequest); Check(readback.Status == "pass" && readback.UnsupportedCoverage.Length > 0, "Existing readback validation remains available with explicit unsupported native-provenance boundaries");
        // The supported REST front end calls the same guarded Core workflow.
        // Publish a named user-import copy without introducing a native job.
        var restPreview = await client.PostAsync<StructuralEditPreview>("/api/structural-edits/preview", request);
        Check(restPreview.CanApply && restPreview.PreviewReceipt is not null && restPreview.PlanSha256 == preview.PlanSha256, "Authenticated REST retains the same structural plan/review/receipt guards");
        var restResult = await client.PostAsync<StructuralEditResult>("/api/structural-edits/apply", new StructuralApplyRequest(request, restPreview.ReviewSha256, restPreview.PreviewReceipt!.Id, restPreview.PreviewReceipt.Sha256));
        var restStatus = await client.GetAsync<StructuralEditStatus>($"/api/structural-edits/previews/{restPreview.PreviewReceipt.Id}?expectedSha256={restPreview.PreviewReceipt.Sha256}");
        Check(restStatus.Status == "applied" && restStatus.Result?.Candidate.Id == restResult.Candidate.Id, "REST status reconciles the exact completed apply without replay");
        var destinationPath = Path.Combine(root, "artifacts", "exports", "Structural_edited_review.L5X");
        var saved = await client.PostAsync<SavedArtifact>($"/api/artifacts/{restResult.Candidate.Id}/save", new SaveArtifactRequest(destinationPath));
        var savedBytes = await File.ReadAllBytesAsync(destinationPath);
        Check(saved.Path == destinationPath && saved.Sha256 == restResult.Candidate.Sha256 && ProjectService.Hash(savedBytes) == saved.Sha256 && savedBytes.SequenceEqual(expected), "Named L5X is delivered to the requested allowed folder and exact file/artifact hash readback matches");
        Check(ProjectService.Hash(await File.ReadAllBytesAsync(path)) == project.SourceSha256 && restResult.NativeAcceptance == "not-performed", "Prompt file delivery preserves the original and leaves user-owned native import unclaimed");
        var sdk = await client.GetAsync<SdkJob[]>("/api/sdk/jobs"); Check(sdk.Length == 0, "Focused structural fixture starts no native SDK job or controller operation");
        var output = Path.Combine(root, "artifacts", "test-results", "structural-integration.json"); Directory.CreateDirectory(Path.GetDirectoryName(output)!); await File.WriteAllTextAsync(output, JsonSerializer.Serialize(new { passed = checks.Count, checks, controllerConnectionAttempted = false, nativeBridgeExecuted = false }, ProjectService.Json)); Console.WriteLine($"{checks.Count} focused structural API/MCP checks passed.");
    }
}
